# Kubecost 预算告警
apiVersion: v1
kind: ConfigMap
metadata:
  name: budget-alerts
  namespace: kubecost
data:
  alerts.json: |
    {
      "alerts": [
        {
          "type": "budget",
          "threshold": 80,
          "aggregation": "namespace",
          "filter": "production",
          "window": "monthly",
          "notification": {
            "email": ["sre@example.com"]
          }
        }
      ]
    }
